        )

    return name, opts, secondary_opts

def add_to_parser(self, parser: OptionParser, ctx: Context) -> None:
    if self.multiple:
        action = "append"
    elif self.count:
        action = "count"
    else:
        action = "store"

    if self.is_flag:
        action = f"{action}_const"

        if self.is_bool_flag and self.secondary_opts:
            parser.add_option(
                obj=self, opts=self.opts, dest=self.name, action=action, const=True
            )
            parser.add_option(
                obj=self,
                opts=self.secondary_opts,
                dest=self.name,
                action=action,
                const=False,
            )
        else:
            parser.add_option(
                obj=self,
                opts=self.opts,
                dest=self.name,
                action=action,
                const=self.flag_value,
            )
    else:
        parser.add_option(
            obj=self,
            opts=self.opts,
            dest=self.name,
            action=action,
            nargs=self.nargs,
        )

def get_help_record(self, ctx: Context) -> t.Optional[t.Tuple[str, str]]:
    if self.hidden:
        return None

    any_prefix_is_slash = False

    def _write_opts(opts: t.Sequence[str]) -> str:
        nonlocal any_prefix_is_slash

        rv, any_slashes = join_options(opts)

        if any_slashes:
            any_prefix_is_slash = True

        if not self.is_flag and not self.count:
            rv += f" {self.make_metavar()}"

        return rv

    rv = [_write_opts(self.opts)]

    if self.secondary_opts:
        rv.append(_write_opts(self.secondary_opts))

    help = self.help or ""
    extra = []

import click
from click.testing import CliRunner

runner = CliRunner()

# 1. plain bool flag with envvar
@click.command()
@click.option("--flag", is_flag=True, envvar="FLAG")
def cli1(flag):
    return flag
r = runner.invoke(cli1, [], env={"FLAG": "1"}, standalone_mode=False)
print("1 bool flag envvar:", r.return_value, r.exit_code, r.exception)

# 2. bool flag pair with envvar
@click.command()
@click.option("--flag/--no-flag", envvar="FLAG")
def cli2(flag):
    return flag
for v in ("1", "0", "true", "false"):
    r = runner.invoke(cli2, [], env={"FLAG": v}, standalone_mode=False)
    print("2 bool pair envvar", v, "->", r.return_value, r.exit_code, r.exception)

# 3. flag_value with is_flag=False and envvar
@click.command()
@click.option("--name", is_flag=False, flag_value="Flag", default="Default", envvar="NAME")
def cli3(name):
    return name
r = runner.invoke(cli3, [], env={"NAME": "Value"}, standalone_mode=False)
print("3 flag_value envvar:", r.return_value, r.exit_code, r.exception)
r = runner.invoke(cli3, ["--name"], standalone_mode=False)
print("3 flag_value no envvar, flag given:", r.return_value)
r = runner.invoke(cli3, [], standalone_mode=False)
print("3 flag_value no envvar:", r.return_value)

# 4. feature switch (flag_value, is_flag implied) with envvar
@click.command()
@click.option("--upper", "transformation", flag_value="upper", default=True, envvar="TRANS")
@click.option("--lower", "transformation", flag_value="lower", envvar="TRANS")
def cli4(transformation):
    return transformation
for env in ({}, {"TRANS": "lower"}):
    r = runner.invoke(cli4, [], env=env, standalone_mode=False)
    print("4 feature switch env", env, "->", r.return_value, r.exit_code, r.exception)

# 5. multiple flag with envvar
@click.command()
@click.option("--flag", is_flag=True, multiple=True, envvar="FLAG")
def cli5(flag):
    return flag
r = runner.invoke(cli5, [], env={"FLAG": "1"}, standalone_mode=False)
print("5 multiple flag envvar:", r.return_value, r.exit_code, r.exception)
r = runner.invoke(cli5, ["--flag"], env={"FLAG": "1"}, standalone_mode=False)
print("5 multiple flag cmdline:", r.return_value, r.exit_code, r.exception)

# 6. count with envvar
@click.command()
@click.option("-v", "--verbose", count=True, envvar="VERBOSE")
def cli6(verbose):
    return verbose
r = runner.invoke(cli6, [], env={"VERBOSE": "3"}, standalone_mode=False)
print("6 count envvar:", r.return_value, r.exit_code, r.exception)

# 7. flag_value explicit with is_flag=True and envvar
@click.command()
@click.option("--flag", is_flag=True, flag_value="custom", envvar="FLAG")
def cli7(flag):
    return flag
r = runner.invoke(cli7, [], env={"FLAG": "1"}, standalone_mode=False)
print("7 flag_value custom envvar:", r.return_value, r.exit_code, r.exception)
r = runner.invoke(cli7, ["--flag"], standalone_mode=False)
print("7 flag_value custom cmdline:", r.return_value)
r = runner.invoke(cli7, [], standalone_mode=False)
print("7 flag_value custom default:", r.return_value)

# 8. envvar with flag_value where envvar is the flag_value string
@click.command()
@click.option("--upper", "transformation", flag_value="upper", envvar="TRANS")
def cli8(transformation):
    return transformation
r = runner.invoke(cli8, [], env={"TRANS": "upper"}, standalone_mode=False)
print("8 feature switch env=flag_value:", r.return_value, r.exit_code, r.exception)
